pid_t pid = fork();
if (pid < 0) {
    perror("fork failed");
} else if (pid == 0) {            /* child */
    execlp("/bin/ls", "ls", NULL);
} else {                          /* parent */
    wait(NULL);                   /* wait for child */
    printf("Child %d done\n", pid);
}

